from datetime import datetime, timedelta
from funcy import cache, SkipMemoization, reraise

calls = []
@cache(60, key_func=lambda x: x.lower())
def cached(x):
    calls.append(x)
    return x.upper()
assert cached.memory == {}
assert cached.skip is SkipMemoization
assert cached('A') == cached('a') == 'A'
assert calls == ['A']
assert cached.memory['a'][0] == 'A'
cached.memory['a'] = ('injected', datetime.now())
assert cached('a') == 'injected'
cached.memory['a'] = ('expired', datetime.now() - timedelta(seconds=61))
assert cached('a') == 'A'
cached.invalidate('A')
assert cached.memory == {}
cached('b')
cached.invalidate_all()
assert cached.memory == {}

seen = []
def transform(error):
    seen.append(error)
    return RuntimeError('converted: ' + str(error))

@reraise(ValueError, transform)
def fail(message):
    raise ValueError(message)
for message in ('one', 'two'):
    try:
        fail(message)
    except RuntimeError as error:
        assert str(error) == 'converted: ' + message
        assert error.__cause__ is seen[-1]
assert len(seen) == 2

class Factory:
    def __call__(self, error):
        return RuntimeError(str(error))

class CallableError(RuntimeError):
    def __call__(self, error):
        raise AssertionError('exception instances must not be invoked')

instance = CallableError('existing')
for target in (RuntimeError, instance, Factory()):
    original = ValueError('original')
    try:
        with reraise(ValueError, target):
            raise original
    except RuntimeError as error:
        assert error.__cause__ is original
        if target is RuntimeError:
            assert error.args == ()
        elif target is instance:
            assert error is instance

try:
    with reraise(ValueError, transform):
        raise KeyError('uncaught')
except KeyError:
    pass
else:
    raise AssertionError('unmatched exception was intercepted')
assert len(seen) == 2
print('Targeted cache and reraise checks passed')
